# Optional Drive timeout supervisor; preserves the original runner and checkpoints.
import base64 as _wd_b64, subprocess as _wd_sp, sys as _wd_sys
from baseline_runtime import read_json as _wd_read, write_json as _wd_write
_wd_path=WORK_ROOT/'storage_watchdog.py'
_wd_source=_wd_b64.b64decode('')
if _wd_path.exists() and _wd_path.read_bytes()!=_wd_source:
    raise ValueError('Watchdog source differs; inspect before replacing it.')
if not _wd_path.exists(): _wd_path.write_bytes(_wd_source)
_wd_pointer=WORK_ROOT/'storage_watchdog_pid.json'
_wd_live=False
if _wd_pointer.exists():
    _wd_saved=_wd_read(_wd_pointer)
    try:
        _wd_raw=Path(f"/proc/{_wd_saved['pid']}/stat").read_text()
        _wd_fields=_wd_raw[_wd_raw.rfind(')')+2:].split()
        _wd_live=_wd_fields[0]!='Z' and _wd_fields[19]==_wd_saved['start_ticks']
    except OSError: pass
if not _wd_live:
    with (WORK_ROOT/'logs/storage_watchdog.log').open('a') as _wd_log:
        _wd_child=_wd_sp.Popen([_wd_sys.executable,'-u',str(_wd_path),str(WORK_ROOT),'--max-retries','5'],stdout=_wd_log,stderr=_wd_sp.STDOUT,start_new_session=True)
    _wd_raw=Path(f'/proc/{_wd_child.pid}/stat').read_text()
    _wd_fields=_wd_raw[_wd_raw.rfind(')')+2:].split()
    _wd_write(_wd_pointer,{'pid':_wd_child.pid,'start_ticks':_wd_fields[19]})
    print('Drive timeout supervisor started:',_wd_child.pid)
else:
    print('Drive timeout supervisor already running:',_wd_saved['pid'])
print(session.status())
if (WORK_ROOT/'storage_watchdog_status.json').exists():
    print(_wd_read(WORK_ROOT/'storage_watchdog_status.json'))

